class ProjectsResource(Resource):
    """Operations on ``projects``, in the Projects module."""

    def list(
        self,
        *,
        limit: Optional[int] = None,
        cursor: Optional[str] = None,
        fields: FieldsArg = None,
        sort: SortArg = None,
        filter: Optional[Filter] = None,
        options: Optional[RequestOptions] = None,
    ) -> Page[Project]:
        """List project rows

        A production project. Jurisdiction is resolved at gate 1. Returns a cursor page of project rows the caller may see. The default order is `created_at` ascending. Supports sparse fieldsets and the filter grammar.

        ``GET /projects`` (operation ``projects.list``).
        Requires the capability ``projects.project.read``.
        """
        return self._client.request_page(OPERATIONS["projects.list"], query={"limit": limit, "cursor": cursor, "fields": fields, "sort": sort, "filter": filter}, options=options)

    def list_all(
        self,
        *,
        limit: Optional[int] = None,
        fields: FieldsArg = None,
        sort: SortArg = None,
        filter: Optional[Filter] = None,
        options: Optional[RequestOptions] = None,
    ) -> Iterator[Project]:
        """List project rows

        A production project. Jurisdiction is resolved at gate 1. Returns a cursor page of project rows the caller may see. The default order is `created_at` ascending. Supports sparse fieldsets and the filter grammar.

        Iterates every item across all pages, following ``next_cursor``.

        ``GET /projects`` (operation ``projects.list``).
        Requires the capability ``projects.project.read``.
        """
        return self._client.paginate(OPERATIONS["projects.list"], query={"limit": limit, "fields": fields, "sort": sort, "filter": filter}, options=options)

    def create(
        self,
        body: ProjectCreate,
        *,
        idempotency_key: Optional[str] = None,
        options: Optional[RequestOptions] = None,
    ) -> ApiResponse[Project]:
        """Create a project

        A production project. Jurisdiction is resolved at gate 1. Creates a project. Requires `Idempotency-Key`; a replay returns the original response. The organization is derived from the credential or the parent row, never from the body.

        ``POST /projects`` (operation ``projects.create``).
        Requires the capability ``projects.project.create``.
        """
        return self._client.request(OPERATIONS["projects.create"], body=body, idempotency_key=idempotency_key, options=options)

    def get(
        self,
        id: str,
        *,
        fields: FieldsArg = None,
        options: Optional[RequestOptions] = None,
    ) -> ApiResponse[Project]:
        """Get a project

        A production project. Jurisdiction is resolved at gate 1. Returns one project with its `ETag`. A project the caller may not see returns 404.

        ``GET /projects/{id}`` (operation ``projects.get``).
        Requires the capability ``projects.project.read``.
        """
        return self._client.request(OPERATIONS["projects.get"], path={"id": id}, query={"fields": fields}, options=options)

    def update(
        self,
        id: str,
        body: ProjectUpdate,
        *,
        if_match: str,
        options: Optional[RequestOptions] = None,
    ) -> ApiResponse[Project]:
        """Update a project

        A production project. Jurisdiction is resolved at gate 1. Updates the fields sent; omitted fields are unchanged. Requires `If-Match` with the current `ETag`: a stale tag returns 412 and a missing tag returns 428.

        ``PATCH /projects/{id}`` (operation ``projects.update``).
        Requires the capability ``projects.project.write``.
        """
        return self._client.request(OPERATIONS["projects.update"], path={"id": id}, body=body, if_match=if_match, options=options)

    def transition(
        self,
        id: str,
        body: ProjectTransitionRequest,
        *,
        idempotency_key: Optional[str] = None,
        options: Optional[RequestOptions] = None,
    ) -> ApiResponse[Project]:
        """Transition the project state

        Moves the project lifecycle to another state through its transition RPC, which writes the transition ledger. Uses compare-and-set on `expected_state`; a disallowed transition returns a 422 refusal. Requires `Idempotency-Key`; a replay returns the original response. A rule that refuses the request returns 422 with `refusal` and `reason`.

        ``POST /projects/{id}/transitions`` (operation ``projects.transition``).
        Requires the capability ``projects.project.archive``.
        """
        return self._client.request(OPERATIONS["projects.transition"], path={"id": id}, body=body, idempotency_key=idempotency_key, options=options)

    def pass_gate(
        self,
        id: str,
        body: GateTransitionRequest,
        *,
        idempotency_key: Optional[str] = None,
        options: Optional[RequestOptions] = None,
    ) -> ApiResponse[Project]:
        """Pass the current gate

        Moves the project to the next phase. Compare-and-set on `expected_phase_code`; refused with 422 when any blocking criterion lacks evidence. The database enforces the criteria. Requires `Idempotency-Key`; a replay returns the original response. A rule that refuses the request returns 422 with `refusal` and `reason`.

        ``POST /projects/{id}/gate-transitions`` (operation ``projects.passGate``).
        Requires the capability ``projects.gate.transition``.
        """
        return self._client.request(OPERATIONS["projects.passGate"], path={"id": id}, body=body, idempotency_key=idempotency_key, options=options)

    def gate_readiness(
        self,
        id: str,
        *,
        options: Optional[RequestOptions] = None,
    ) -> ApiResponse[GateReadinessPage]:
        """Get gate readiness

        Lists each criterion of the next gate with whether evidence satisfies it. A rule that refuses the request returns 422 with `refusal` and `reason`.

        ``GET /projects/{id}/gate-readiness`` (operation ``projects.gateReadiness``).
        Requires the capability ``projects.gate.read``.
        """
        return self._client.request(OPERATIONS["projects.gateReadiness"], path={"id": id}, options=options)

    def archive(
        self,
        id: str,
        *,
        idempotency_key: Optional[str] = None,
        options: Optional[RequestOptions] = None,
    ) -> ApiResponse[Project]:
        """Archive a project

        Sets `archived_at`, so the project leaves the default lists and stays readable and restorable. Archiving an archived project leaves it unchanged. Requires `Idempotency-Key`; a replay returns the original response. A rule that refuses the request returns 422 with `refusal` and `reason`.

        ``POST /projects/{id}/archive`` (operation ``projects.archive``).
        Requires the capability ``projects.project.archive``.
        """
        return self._client.request(OPERATIONS["projects.archive"], path={"id": id}, idempotency_key=idempotency_key, options=options)

    def unarchive(
        self,
        id: str,
        *,
        idempotency_key: Optional[str] = None,
        options: Optional[RequestOptions] = None,
    ) -> ApiResponse[Project]:
        """Restore an archived project

        Clears `archived_at`, so the project returns to the default lists. Requires `Idempotency-Key`; a replay returns the original response. A rule that refuses the request returns 422 with `refusal` and `reason`.

        ``POST /projects/{id}/unarchive`` (operation ``projects.unarchive``).
        Requires the capability ``projects.project.archive``.
        """
        return self._client.request(OPERATIONS["projects.unarchive"], path={"id": id}, idempotency_key=idempotency_key, options=options)


